_DB = [("Husband", "Hon, ano bang bahay ang gusto mo?", "Hon, what kind of house do you want?"), ("Wife", "Gusto kong may tatlong kuwarto at dalawang banyo.", "I want one with three rooms and two bathrooms."), ("Husband", "Ano pa?", "What else?"), ("Wife", "Gusto kong may dalawang palapag at malaking kusina at salas.", "I want two floors and a big kitchen and living room."), ("Husband", "Gusto mo ba ng sahig na kahoy o marmol?", "Do you want a wood or marble floor?"), ("Wife", "Okey lang ang sahig na kahoy, pero dapat semento ang dingding.", "A wood floor is okay, but the walls should be cement."), ("Husband", "May nakita akong paupahan. Gusto mo bang makita?", "I saw a house for rent. Do you want to see it?"), ("Wife", "Siyempre naman. May oras ako ngayon.", "Of course. I have time now.")]
