        + [F("Naghahanap ako ng ___ malapit sa bayan. (apartment)", "apartment", ["palengke", "upa"], "apartment."), F("Magkano kaya ang ___? (rent)", "upa", ["bayan", "oras"], "upa."), F("Kailan ka ba ___? (will move)", "lilipat", ["magtanong", "nakita"], "lilipat."), F("Gusto kong may dalawang ___ at malaking kusina. (floors)", "palapag", ["banyo", "kahoy"], "palapag."), F("May ___ akong paupahan. (saw)", "nakita", ["makita", "gusto"], "nakita."), F("Okey lang ang sahig na kahoy, ___ dapat semento ang dingding. (but)", "pero", ["sana", "pati"], "pero.")]
