# ------------------------------------------------------------------ 2 deposit, contract, subdivision
_PA = [("Client", "Magkano po ba ang deposito?", "How much is the deposit?"), ("Realtor", "Kailangan ng dalawang buwang deposito at isang buwang advance.", "A two-month deposit and one month advance are needed."), ("Client", "May kontrata po ba?", "Is there a contract?"), ("Realtor", "Meron po. Isang taong kontrata lang.", "There is. Only a one-year contract."), ("Client", "Libre po ba ang tubig at hakot ng basura?", "Are water and trash collection free?"), ("Realtor", "Libre po. Pati internet, kuryente, at cable.", "Free, including internet, electricity and cable."), ("Client", "Maganda kung ganoon.", "That’s good then.")]
