_KEY2 = [("A1. What three questions does the client ask?", "How much is the deposit? Is there a contract? Are water and trash collection free?"), ("A2. What are the required contract and deposit?", "A one-year contract and a 2-month deposit."), ("A3. What five amenities are free?", "Water, trash collection, internet, electricity and cable."), ("B4. What four questions does the woman ask?", "What is the area of the house? Is the backyard wide? Does the subdivision have a security guard? Are there a playground and a school inside?"), ("B5. What two adjectives best describe the subdivision?", "Quiet and safe."), ("B6. What three amenities are mentioned?", "24/7 security, a playground and 2 day care centers.")]
