        + [M("What does Maganda kung ganoon mean?", "That’s good then.", ["That’s too expensive.", "I will think about it.", "It is far away."], "kung ganoon."), M("What does bakod na kongkreto mean?", "concrete fence", ["wooden floor", "wide yard", "big kitchen"], "bakod na kongkreto."), M("Which system of measurement does the Philippines use?", "The metric system", ["The imperial system", "Both equally", "Neither"], "metro kuwadrado."), M("What is the contract length in Dialog A?", "One year", ["Six months", "Two years", "There is no contract"], "isang taong kontrata."), M("How long is the deposit?", "Two months, plus one month advance", ["One month", "Six months", "None"], "dalawang buwang deposito."), M("How many hours a day is the security in the subdivision?", "Twenty-four", ["Eight", "Twelve", "None"], "beynte kuwatro oras."), M("How many day care centers are inside the subdivision?", "Two", ["One", "Three", "None"], "dalawang day care center.")]
