# ------------------------------------------------------------------ 3 may / mayroon
_S1 = [("Merong palaruan, at may dalawang day care center.", "There is a playground, and there are two day care centers."), ("May kontrata po ba?", "Is there a contract, sir/ma’am?"), ("Meron po, isang taong kontrata lang.", "There is, sir/ma’am, only a one-year contract."), ("May guwardiya po ba sa sabdibisyon?", "Is there a guard in the subdivision?"), ("Merong guwardiya.", "There is a guard."), ("May palaruan po ba at paaralan sa loob?", "Are there a playground and a school inside?")]
_LK = [("Merong tatlong kuwarto at dalawang banyo sa bahay na ito.", "There are three bedrooms and two bathrooms in this house."), ("Mayroong sakayan ng bus malapit sa paupahang bahay.", "There is a bus stop near the rental house.")]
