_MO = [("Meron raw bang paaralan sa paupahan?", "Is there reportedly a school at the rental? (Me/May raw is wrong; Meron/Mayroon raw is right.)"), ("May tubig na.", "There is water already. (Not May na tubig.)"), ("Meron nang tubig.", "There is water already. (Meron/Mayroon can come before a monosyllabic word.)"), ("May guwardiya po ba rito sa sabdibisyon?", "Is there a guard here in the subdivision? (Not Me/May po bang guwardiya.)"), ("Meron po bang guwardiya rito sa sabdibisyon?", "Is there a guard here in the subdivision? (Meron/Mayroon can come before po.)")]
_A1 = [("Walang tao sa bahay.", "There is nobody at home."), ("May bakuran ba?", "Is there a yard?"), ("Mayroon bang bakuran?", "Is there a yard?"), ("May malapit na pamantasan sa amin.", "There is a nearby university near us."), ("May pamantasang malapit sa amin.", "There is a university near us."), ("Wala pang kuryente hanggang ngayon.", "There is still no electricity until now."), ("May kuryente na ngayon.", "There is electricity now."), ("Meron nang kuryente ngayon.", "There is electricity now.")]
L3 = lesson(
    "C6 L1 · May and mayroon: “there is / there are”",
    "May kontrata po ba? · Merong guwardiya · Wala pang kuryente · May tubig na",
    requires=[],
    cards=[
        card("May / me and mayroon / meron", "May and mayroon, with the colloquial forms me and meron, have three uses; this lesson covers one. Depending on context they are equivalent to the English existential phrase “there is / there are / there will be.” These verbs are not conjugated: time or tense comes from context or from the adverbs of time in the sentence. Wala is the negative counterpart and here means “there is/are/will be none.” The two other uses of may/mayroon and wala come in later lessons.", examples=passage(_S1)),
        card("Rule 1: always link mayroon and meron to the noun", "Mayroon and meron take the linker g (mayroong, merong) before the noun they refer to.", examples=passage(_LK)),
        card("Rule 2: may and maraming are never in the same sentence", "English says “There are many rooms in the house”, but Tagalog says Maraming kuwarto sa bahay, not May maraming kuwarto sa bahay. Maraming already means “there are many”; note the linker ng with marami.", examples=passage(_MM)),
        card("Rule 3: me / may cannot come before a monosyllabic word; meron / mayroon can", "The book’s examples: Wrong Me/May raw bang paaralan sa paupahan? Right Meron/Mayroon raw bang paaralan sa paupahan? Wrong Me/May na tubig. Right Me/May tubig na. Right Meron/Mayroon nang tubig. Wrong Me/May po bang guwardiya rito sa sabdibisyon? Right Me/May guwardiya po ba rito sa sabdibisyon? Right Meron/Mayroon po bang guwardiya rito sa sabdibisyon? (Raw, na and po are one-syllable words.)", examples=passage(_MO)),
        card("Activity 1: complete with may, me, mayroon, meron, or wala (the lesson’s answers)", "The book lists several acceptable answers for each blank and prints no key; these are the completed sentences.", examples=passage(_A1)),
        card("Activities left out", "None beyond the audio."),
    ],
    exercises=uniq(
        tr_q(_S1) + tr_q(_LK) + rev_q(_LK) + tr_q(_A1) + rev_q(_A1)
        + [M("What does Wala mean in this lesson?", "there is/are none", ["there is/are many", "there was", "I don’t know"], "wala."), M("Are may and mayroon conjugated for tense?", "No, tense comes from context", ["Yes, like mag verbs", "Yes, like um verbs", "Only in the past"], "Not conjugated."), M("Which linker goes with mayroon before a noun?", "g (mayroong)", ["na", "ng only before vowels", "no linker"], "mayroong."), M("Which sentence is correct?", "Maraming kuwarto sa bahay.", ["May maraming kuwarto sa bahay.", "Meron maraming kuwarto sa bahay.", "Mayroon maraming kuwarto."], "No may + maraming."), M("Which is correct?", "May tubig na.", ["May na tubig.", "Me na tubig.", "Meron na tubig."], "May before the noun, na after it."), M("Which is correct?", "Meron nang tubig.", ["May nang tubig.", "Me nang tubig.", "Meron na ang tubig."], "Meron before a monosyllable."), M("Which is correct?", "May guwardiya po ba rito?", ["May po bang guwardiya rito?", "Me po bang guwardiya rito?", "Me po ba guwardiya rito?"], "May before po is wrong."), M("Which is correct?", "Meron po bang guwardiya rito?", ["May po bang guwardiya rito?", "Me po bang guwardiya rito?", "May po ba bang guwardiya rito?"], "Meron can precede po."), M("What does Wala pang kuryente mean?", "There is still no electricity.", ["There is electricity.", "The electricity is free.", "The electricity is expensive."], "wala pang."), M("How do you say “There is a guard.”?", "Merong guwardiya.", ["Merong maraming guwardiya.", "Maraming merong guwardiya.", "Meron guwardiya."], "Merong guwardiya.")]
        + [F("___ tao sa bahay. (There is nobody)", "Walang", ["Merong", "Mayroong"], "walang."), F("___ bakuran ba? (Is there a yard?)", "May", ["Wala", "Walang"], "may."), F("___ bang bakuran? (Is there a yard?)", "Mayroon", ["May", "Me"], "mayroon."), F("___ pang kuryente hanggang ngayon. (still none)", "Wala", ["Meron", "Mayroon"], "wala pang."), F("___ nang kuryente ngayon. (There is now)", "Meron", ["May", "Me"], "meron nang."), F("___ kuwarto sa bahay. (many)", "Maraming", ["May maraming", "Merong"], "maraming."), F("Merong ___ kuwarto at dalawang banyo sa bahay. (three, linked)", "tatlong", ["tatlo", "tatlongka"], "tatlong."), F("May ___ na ngayon. (electricity)", "kuryente", ["kahoy", "marmol"], "may kuryente na.")]
    ),
)

